mapper.select:
SELECT COUNT(1)
FROM crm_website_page_view
WHERE session_id = #{sessionId}
  AND page_url = #{pageUrl}
  AND viewed_at >= (#{viewedAt}::timestamptz - (#{withinSeconds} || ' seconds')::interval)
  AND viewed_at <= (#{viewedAt}::timestamptz + (#{withinSeconds} || ' seconds')::interval)

SELECT COUNT(1)
FROM crm_website_page_view
WHERE session_id = #{sessionId}
  AND page_url = #{pageUrl}
  AND ABS(EXTRACT(EPOCH FROM (viewed_at - #{viewedAt}::timestamptz))) < #{withinSeconds}
